<?php
$steps=['confirmed'=>'Sipariş alındı','preparing'=>'Hazırlanıyor','shipped'=>'Kargoya verildi','in_transit'=>'Yolda','delivered'=>'Teslim edildi'];
$current=$o['status']==='paid'?'confirmed':$o['status'];$position=array_search($current,array_keys($steps),true);
?>
<section class="panel order-progress" aria-label="Sipariş takibi"><div class="spread"><div><span class="eyebrow">SİZE ÖZEL SİPARİŞ TAKİP KODU</span><p class="tracking-code"><strong><?=e($o['tracking_code'])?></strong></p></div><a class="button" href="<?=e(url('order',['id'=>$o['id'],'key'=>$o['secret']]))?>">Durumu yenile</a></div><p>Bu kodu ve siparişte kullandığınız e-postayı “Sipariş takibi” sayfasına girerek güncel durumu görebilirsiniz. Kargo firmasının takip numarası ayrıca aşağıda gösterilir.</p>
<?php if($position!==false):?><ol class="delivery-steps"><?php foreach($steps as $key=>$label):$i=array_search($key,array_keys($steps),true);?><li class="<?=$i<=$position?'complete':''?>" <?=$i===$position?'aria-current="step"':''?>><span><?=$i<$position?'✓':$i+1?></span><strong><?=e($label)?></strong></li><?php endforeach?></ol><?php else:?><p class="notice"><?=e($statuses[$o['status']]??$o['status'])?>. Teslimat adımları sipariş onaylandıktan sonra başlar.</p><?php endif?>
<details class="order-history"><summary>Durum geçmişi</summary><ol><?php foreach(query('SELECT * FROM order_events WHERE order_id=? ORDER BY id',[$o['id']])->fetchAll() as $event):?><li><time><?=e($event['created'])?></time> — <?=e($statuses[$event['status']]??$event['status'])?><?=$event['source']==='migration'?' (güncelleme sırasında mevcut durum)':''?></li><?php endforeach?></ol></details></section>
